window.products.push({"id":89561,"name":"Tea Ball Strainers (mesh teaball)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/614rNhcaSiL._AC_SL1000_.jpg","description":"Unique design: The Astronaut handle protects you from heating up and burning your fingers because of the hot water Premium stainless steel: Made from 18/8 304 stainless steel, the steel ball's holes reduces unwanted leaves floating in your cup, allow the water to move through the tea leaves but keeps most of them in the steel ball and out of your cup. Easy to use: Suitable for all kinds of loose tea including medium to large tea leafs","images":["https://m.media-amazon.com/images/I/614rNhcaSiL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Meelio","source_asin":"B06XXZH17T","category_path":"Home & Appliances"},"sku":"BM-89561","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B06XXZH17T","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B06XXZH17T","price_pending":true,"merchant_ready":false});
